return function(scope, p, callback, p2, p3)
	local v = {
		Name = "Panel",
		Visible = p3,
		[p] = { callback({
				Text = p2
			}), scope:New("Frame")({
				Name = "Body"
			}) }
	}
	return scope:New("Frame")(v)
end

