return function(scope, p, callback, p2, p3)
	local v = {
		Name = "Panel"
	}

	if p3 then
		v.BackgroundTransparency = 0
	else
		v.BackgroundTransparency = 1
	end

	v[p] = { callback({
			Text = p2
		}) }
	return scope:New("Frame")(v)
end

return function(p)
	return 0 + p * 1 + p * 2 + p * 3 + p * 4
end
